<?php
require "../includes/auth.php";require "../config/database.php";$page_title="Jadwal";$active="jadwal";
if(isset($_GET["delete"])){$conn->query("DELETE FROM jadwal WHERE id=".(int)$_GET["delete"]);header("Location: jadwal.php");exit;}
$edit=null;if(isset($_GET["edit"]))$edit=$conn->query("SELECT * FROM jadwal WHERE id=".(int)$_GET["edit"])->fetch_assoc();
if(isset($_POST["save"])){$id=(int)$_POST["id"];$pid=(int)$_POST["pasien_id"];$did=(int)$_POST["dokter_id"];$tgl=$conn->real_escape_string($_POST["tanggal"]);$waktu=$conn->real_escape_string($_POST["waktu"]);$st=$conn->real_escape_string($_POST["status"]);$sql=$id?"UPDATE jadwal SET pasien_id=$pid,dokter_id=$did,tanggal='$tgl',waktu='$waktu',status='$st' WHERE id=$id":"INSERT INTO jadwal(pasien_id,dokter_id,tanggal,waktu,status)VALUES($pid,$did,'$tgl','$waktu','$st')";$conn->query($sql);header("Location: jadwal.php");exit;}require "../includes/header.php";?>
<div class="page-head"><div><div class="eyebrow">OPERASIONAL</div><h1>Appointment</h1><p>Atur jadwal kunjungan pasien.</p></div><a class="btn primary" href="?action=add">＋ Buat Appointment</a></div>
<?php if(isset($_GET["action"])||$edit):?><div class="panel form-panel"><div class="panel-head"><h3><?=$edit?"Edit Appointment":"Buat Appointment"?></h3><a href="jadwal.php">×</a></div><form method="post"><input type="hidden" name="id" value="<?=$edit["id"]??0?>"><div class="form-grid"><label>Pasien<select name="pasien_id"><?php $ps=$conn->query("SELECT * FROM pasien ORDER BY nama");while($x=$ps->fetch_assoc()):?><option value="<?=$x["id"]?>" <?=($edit["pasien_id"]??"")==$x["id"]?"selected":""?>><?=$x["nama"]?></option><?php endwhile;?></select></label><label>Dokter<select name="dokter_id"><?php $ds=$conn->query("SELECT * FROM dokter ORDER BY nama");while($x=$ds->fetch_assoc()):?><option value="<?=$x["id"]?>" <?=($edit["dokter_id"]??"")==$x["id"]?"selected":""?>><?=$x["nama"]?></option><?php endwhile;?></select></label><label>Tanggal<input type="date" name="tanggal" required value="<?=$edit["tanggal"]??date("Y-m-d")?>"></label><label>Waktu<input type="time" name="waktu" required value="<?=$edit["waktu"]??"09:00"?>"></label><label>Status<select name="status"><option>Menunggu</option><option <?=($edit["status"]??"")==="Selesai"?"selected":""?>>Selesai</option><option <?=($edit["status"]??"")==="Batal"?"selected":""?>>Batal</option></select></label></div><div class="actions"><a class="btn outline" href="jadwal.php">Batal</a><button class="btn primary" name="save">Simpan</button></div></form></div><?php endif;?>
<div class="panel"><div class="table-tools"><div class="search-table">⌕ <input id="search" onkeyup="filterTable('search','scheduleTable')" placeholder="Cari jadwal..."></div></div><table id="scheduleTable"><thead><tr><th>Waktu</th><th>Pasien</th><th>Dokter</th><th>Tanggal</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php $q=$conn->query("SELECT j.*,p.nama pasien,d.nama dokter FROM jadwal j JOIN pasien p ON p.id=j.pasien_id JOIN dokter d ON d.id=j.dokter_id ORDER BY j.tanggal DESC,j.waktu DESC");while($r=$q->fetch_assoc()):?><tr><td><b><?=substr($r["waktu"],0,5)?></b></td><td><?=$r["pasien"]?></td><td><?=$r["dokter"]?></td><td><?=date("d M Y",strtotime($r["tanggal"]))?></td><td><span class="badge <?=$r["status"]==="Selesai"?"success":($r["status"]==="Batal"?"danger":"pending")?>"><?=$r["status"]?></span></td><td class="actions-cell"><a class="edit" href="?edit=<?=$r["id"]?>">Edit</a><a class="delete" onclick="return confirm('Hapus appointment?')" href="?delete=<?=$r["id"]?>">Hapus</a></td></tr><?php endwhile;?></tbody></table></div><?php require "../includes/footer.php";?>